/// A validated legacy loose-row path derived with the v1 path codec.
/// Format-1/2 snapshots address rows by this path; format-3 rows have none.
#[derive(Clone, Debug, Eq, Hash, PartialEq)]
pub struct LoosePath(ManagedPath);

impl LoosePath {
    /// Admits a discovered table-relative encoded row path. The components
    /// exclude the table root and include the final `.orna` extension.
    /// Decoding rejects aliases before construction; this does not perform
    /// filesystem I/O, resolve symlinks, or interpret the key's logical type.
    pub fn from_encoded_key(
        table_root: impl AsRef<str>,
        components: &[String],
    ) -> Result<Self, Error> {
        let key = path_decode_key_components(components).map_err(|_| Error::InvalidKey)?;
        Self::for_key(table_root, &key)
    }

    /// `key` contains canonical text leaves in declared order. The catalogue
    /// flattens tuples and table references to those leaves; storage owns only
    /// their portable path encoding and does not embed referenced rows.
    pub fn for_key(table_root: impl AsRef<str>, key: &[String]) -> Result<Self, Error> {
        let root = table_root.as_ref();
        if root.is_empty() || root.starts_with('.') || root.contains('/') || root.contains('\\') {
            return Err(Error::InvalidTableRoot);
        }
        let components = path_encode_key_components(key).map_err(|_| Error::InvalidKey)?;
        // Logical keys may contain separators, traversal spellings, or empty
        // strings. Only their encoded filesystem components require this check.
        path_validate_relative_components(&components).map_err(|_| Error::InvalidKey)?;
        let path = format!("{root}/{}", components.join("/"));
        ManagedPath::new(path)
            .map(Self)
            .map_err(|_| Error::UnsafePath)
    }

    pub fn as_managed_path(&self) -> &ManagedPath {
        &self.0
    }
}

impl Ord for LoosePath {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.0.as_path().cmp(other.0.as_path())
    }
}

impl PartialOrd for LoosePath {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

fn build_private_publication_candidate_with_store_root(
    repository: &Repository,
    expected_head: &GitCommitRef,
    graph: &NativeGraphContext,
    store_root: &NativeOid,
    message: &str,
) -> Result<PrivateCommit, Error> {
    repository
        .build_private_commit_with_store_root(
            expected_head,
            graph,
            store_root,
            message,
        )
        .map_err(|_| Error::RepositoryUnavailable)
}

struct ProjectedStoreRow {
    base_present: bool,
    next: Option<Vec<u8>>,
}

#[derive(Clone, Debug)]
struct CommittedProjectionSchema {
    descriptor: SchemaDescriptor,
    text_primary_key: bool,
    stored_field_count: usize,
}

pub struct ProjectedRuntimeMutation {
    pub key: Vec<u8>,
    pub rekey_to: Option<Vec<u8>>,
    pub value: Option<Vec<u8>>,
}

fn schema_descriptor_entry(
    schema: &SchemaDescriptor,
    number: i64,
) -> Result<&OvbRaw, Error> {
    let OvbRaw::Map(entries) = schema.raw() else {
        return Err(Error::RepositoryUnavailable);
    };
    let key = OvbRaw::Int(number.into());
    entries
        .iter()
        .find(|(candidate, _)| candidate == &key)
        .map(|(_, value)| value)
        .ok_or(Error::RepositoryUnavailable)
}

fn committed_projection_schema(
    descriptor: SchemaDescriptor,
) -> Result<CommittedProjectionSchema, Error> {
    let OvbRaw::Array(key_ids) = schema_descriptor_entry(&descriptor, 2)? else {
        return Err(Error::RepositoryUnavailable);
    };
    let OvbRaw::Array(declared_fields) = schema_descriptor_entry(&descriptor, 3)? else {
        return Err(Error::RepositoryUnavailable);
    };
    let text_primary_key = if key_ids.len() == 1 {
        let field = declared_fields
            .iter()
            .find(|candidate| {
                matches!(candidate, OvbRaw::Array(parts) if parts.first() == key_ids.first())
            })
            .ok_or(Error::RepositoryUnavailable)?;
        let OvbRaw::Array(parts) = field else {
            return Err(Error::RepositoryUnavailable);
        };
        let OvbRaw::Array(type_node) = parts.get(2).ok_or(Error::RepositoryUnavailable)? else {
            return Err(Error::RepositoryUnavailable);
        };
        matches!(
            type_node.as_slice(),
            [OvbRaw::Int(code), OvbRaw::Text(name)]
                if code == &0.into() && name == "Str"
        )
    } else {
        false
    };
    let stored_field_count = declared_fields.iter().try_fold(0usize, |count, field| {
        let OvbRaw::Array(parts) = field else {
            return Err(Error::RepositoryUnavailable);
        };
        let role = parts.get(3).ok_or(Error::RepositoryUnavailable)?;
        Ok(count + usize::from(matches!(role, OvbRaw::Int(role) if role == &1.into())))
    })?;
    Ok(CommittedProjectionSchema {
        descriptor,
        text_primary_key,
        stored_field_count,
    })
}

/// Projects the runtime row carrier only at the publication boundary. Text
/// primary keys arrive as UTF-8 and become canonical typed keys; every other
/// key must already be canonical. Stored-field arrays pass through byte-exact,
/// while a scalar is wrapped byte-exactly only for a one-field committed
/// schema. The descriptor comes from the row map at the pinned expected head.

fn project_runtime_key(
    schema: &CommittedProjectionSchema,
    relation_id: [u8; 16],
    bytes: &[u8],
) -> Result<Vec<u8>, Error> {
    let key = if schema.text_primary_key {
        let text = std::str::from_utf8(bytes).map_err(|_| Error::RepositoryUnavailable)?;
        TypedKey::Text(text.to_owned())
            .canonical_bytes()
            .map_err(|_| Error::RepositoryUnavailable)?
    } else {
        bytes.to_vec()
    };
    schema
        .descriptor
        .validate_stored_key(relation_id, &key)
        .map_err(|_| Error::RepositoryUnavailable)?;
    Ok(key)
}

/// Converts runtime keys to the committed store-key representation.
/// Single-`Str` keys arrive as UTF-8; other shapes arrive canonical.
pub fn canonicalize_runtime_key(
    descriptor: &SchemaDescriptor,
    relation_id: [u8; 16],
    bytes: &[u8],
) -> Result<Vec<u8>, Error> {
    let schema = committed_projection_schema(descriptor.clone())?;
    project_runtime_key(&schema, relation_id, bytes)
}

fn project_runtime_mutation(
    schema: &CommittedProjectionSchema,
    relation_id: [u8; 16],
    mutation: &TableMutation,
    value_context: &Format3Context,
) -> Result<ProjectedRuntimeMutation, Error> {
    let project_key = |bytes: &[u8]| project_runtime_key(schema, relation_id, bytes);
    let key = project_key(mutation.key())?;
    let rekey_to = mutation.rekey_to().map(project_key).transpose()?;
    let value = mutation
        .value()
        .map(|bytes| {
            let row_key = rekey_to.as_deref().unwrap_or(key.as_slice());
            let decoded = ContextValue::decode_in_context(
                bytes,
                ValueFormat::Rov3,
                value_context,
            )
            .map_err(|_| Error::RepositoryUnavailable)?;
            let fields = if schema
                .descriptor
                .validate_stored_row(relation_id, row_key, bytes)
                .is_ok()
            {
                bytes.to_vec()
             } else if schema.stored_field_count == 1 {
                 let fields = ContextValue::new_in_context(
                     value_context,
                     ValueFormat::Rov3,
                     Raw::Array(vec![decoded.raw().clone()]),
                 )
                 .and_then(|value| value.encode())
                 .map_err(|_| Error::RepositoryUnavailable)?;
                 fields
             } else {
                bytes.to_vec()
             };
            schema
                .descriptor
                .validate_stored_row(relation_id, row_key, &fields)
                .map_err(|_| Error::RepositoryUnavailable)?;
            Ok(fields)
        })
        .transpose()?;
    Ok(ProjectedRuntimeMutation {
        key,
        rekey_to,
        value,
    })
}
/// Projects a runtime mutation with the committed schema and format context.
/// This is the same key and row normalization used by publication.
pub fn project_runtime_mutation_for_descriptor(
    descriptor: &SchemaDescriptor,
    relation_id: [u8; 16],
    mutation: &TableMutation,
    value_context: &Format3Context,
) -> Result<ProjectedRuntimeMutation, Error> {
    let schema = committed_projection_schema(descriptor.clone())?;
    project_runtime_mutation(&schema, relation_id, mutation, value_context)
}

fn build_frozen_publication_store_root(
    repository: &Repository,
    expected_head: &GitCommitRef,
    mutations: &[TableMutation],
) -> Result<
    (
        NativeGraphContext,
        NativeOid,
        Vec<PublicationLogicalRowRekey>,
    ),
    Error,
> {
    let format = repository
        .open_format_context_at_selector(expected_head.as_str())
        .map_err(|_| Error::RepositoryUnavailable)?;
    if format.repository_format() != RepositoryFormat::Format3 {
        return Err(Error::RepositoryUnavailable);
    }

    let mut relation_bases = BTreeMap::new();
    let mut projected_rows = BTreeMap::<([u8; 16], Vec<u8>), ProjectedStoreRow>::new();
    let mut operations_by_relation = BTreeMap::<[u8; 16], Vec<RowIndexMutation>>::new();
    let mut logical_rekeys = Vec::new();
    for mutation in mutations {
        let relation_id = mutation
            .table_object_id()
            .ok_or(Error::RepositoryUnavailable)?
            .bytes();
        if !relation_bases.contains_key(&relation_id) {
            let rows = format
                .load_row_map(relation_id)
                .map_err(|_| Error::RepositoryUnavailable)?;
            let graph = format
                .open_native_graph(&rows)
                .map_err(|_| Error::RepositoryUnavailable)?;
            let scope = graph
                .open_read_scope()
                .map_err(|_| Error::RepositoryUnavailable)?;
            let descriptor = graph
                .read_schema_descriptor(&scope)
                .map_err(|_| Error::RepositoryUnavailable)?;
            let schema = committed_projection_schema(descriptor)?;
            let value_context = format
                .open_value_context(relation_id)
                .map_err(|_| Error::RepositoryUnavailable)?;
            relation_bases.insert(relation_id, (rows, graph, schema, value_context));
        }
        let (_, _, schema, value_context) = relation_bases
            .get(&relation_id)
            .ok_or(Error::RepositoryUnavailable)?;
        operations_by_relation.entry(relation_id).or_default();

        let projected = project_runtime_mutation(schema, relation_id, mutation, value_context)?;
        if let Some(new_key) = projected.rekey_to.as_ref() {
            logical_rekeys.push(
                PublicationLogicalRowRekey::new(
                    relation_id,
                    projected.key.clone(),
                    new_key.clone(),
                )
                .map_err(|_| Error::RepositoryUnavailable)?,
            );
        }
        let source = projected_rows
            .entry((relation_id, projected.key))
            .or_insert_with(|| ProjectedStoreRow {
                base_present: !mutation.is_insert(),
                next: None,
            });
        if let Some(next_key) = projected.rekey_to {
            source.next = None;
            projected_rows
                .entry((relation_id, next_key))
                .or_insert_with(|| ProjectedStoreRow {
                    base_present: false,
                    next: None,
                })
                .next = projected.value;
        } else {
            source.next = projected.value;
        }
    }

    for ((relation_id, key), row) in projected_rows {
        let operations = operations_by_relation
            .get_mut(&relation_id)
            .ok_or(Error::RepositoryUnavailable)?;
        if row.base_present {
            operations.push(
                RowIndexMutation::delete_canonical(&key)
                    .map_err(|_| Error::RepositoryUnavailable)?,
            );
        }
        if let Some(value) = row.next {
            operations.push(
                RowIndexMutation::insert_canonical(&key, &value)
                    .map_err(|_| Error::RepositoryUnavailable)?,
            );
        }
    }

    let mut relation_candidates = Vec::with_capacity(operations_by_relation.len());
    for (relation_id, operations) in operations_by_relation {
        let (rows, graph, _, _) = relation_bases
            .remove(&relation_id)
            .ok_or(Error::RepositoryUnavailable)?;
        let maintenance = if operations.is_empty() {
            None
        } else {
            let scope = graph
                .open_read_scope()
                .map_err(|_| Error::RepositoryUnavailable)?;
            Some(
                graph
                    .maintain_row_index(&operations, &scope)
                    .map_err(|_| Error::RepositoryUnavailable)?,
            )
        };
        relation_candidates.push((rows, graph, maintenance));
    }

    let Some((_, base_graph, _)) = relation_candidates.first() else {
        return Err(Error::IncompleteStaging);
    };
    // A publication that changes rows also records the allocator watermark
    // known when it is made (ORNA-AUTOID-005); a no-op prefix stays a no-op.
    let rows_changed = relation_candidates.iter().any(|(rows, _, maintenance)| {
        maintenance
            .as_ref()
            .is_some_and(|maintenance| maintenance.primary_root() != rows.version().primary_root())
    });
    let allocator_summary = if rows_changed {
        repository
            .allocator_summary_maintenance(expected_head)
            .map_err(|_| Error::RepositoryUnavailable)?
    } else {
        None
    };
    let scope = base_graph
        .open_read_scope()
        .map_err(|_| Error::RepositoryUnavailable)?;
    let candidates = relation_candidates
        .iter()
        .filter_map(|(rows, _, maintenance)| {
            maintenance
                .as_ref()
                .map(|maintenance| (rows.version(), maintenance))
        })
        .chain(
            allocator_summary
                .iter()
                .map(|(rows, maintenance)| (rows.version(), maintenance)),
        )
        .collect::<Vec<_>>();
    let store_root = base_graph
        .maintain_relations_rows(&candidates, &scope)
        .map_err(|_| Error::RepositoryUnavailable)?;
    let (_, graph, _) = relation_candidates.swap_remove(0);
    Ok((graph, store_root, logical_rekeys))
}

/// A prepared, runtime-bound publication. Preparation creates only private
/// Git objects and a durable journal; `publish` and `complete` are separate so
/// a crash can be recovered at each PUB-1 boundary.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RuntimePublicationCoordinator {
    expected_index: IndexGeneration,
    candidate: PrivateCommit,
    journal: PublicationJournal,
    // Retain protected transfer evidence across publication until both runtime
    // and journal completion have succeeded.
    protected_source_mutations: Vec<TableMutation>,
}

impl RuntimePublicationCoordinator {
    /// Prepares the exact prefix issued by `runtime` as a format-3 candidate
    /// and fails when that prefix has no visible change. Protected source
    /// mutations are retained from that prefix before any repository
    /// candidate is written.
    pub async fn prepare(
        repository: &Repository,
        runtime: &RuntimeState,
        expected_head: &GitCommitRef,
        expected_index: IndexGeneration,
        freeze: &PublicationFreeze,
        path_for: impl Fn(&TableMutation) -> Result<LoosePath, Error>,
        message: &str,
    ) -> Result<Self, Error> {
        Self::prepare_allow_noop(
            repository,
            runtime,
            expected_head,
            expected_index,
            freeze,
            path_for,
            message,
        )
        .await?
        .ok_or(Error::IncompleteStaging)
    }

    /// Reads the exact typed prefix named by `freeze` and reports the result as
    /// `None` when the frozen prefix is a no-op.
    ///
    /// Only a format-3 snapshot has a row writer. A format-1/2 `expected_head`
    /// keeps its versioned readers but fails with [`Error::LegacyReadOnly`]
    /// before the runtime prefix is read or any Git object is written
    /// (ORNA-UPGRADE-003, ORNA-ROW-013). A prefix whose native store root is
    /// unchanged from the committed snapshot has no visible change: the caller
    /// completes the frozen intent without a commit instead of preparing an
    /// empty publication.
    ///
    /// `_path_for` is unused because format-3 rows have no loose path; it
    /// remains only while existing callers still supply one.
    pub async fn prepare_allow_noop(
        repository: &Repository,
        runtime: &RuntimeState,
        expected_head: &GitCommitRef,
        expected_index: IndexGeneration,
        freeze: &PublicationFreeze,
        _path_for: impl Fn(&TableMutation) -> Result<LoosePath, Error>,
        message: &str,
    ) -> Result<Option<Self>, Error> {
        let format = writable_snapshot_context(repository, expected_head)?;
        let mutations = runtime
            .pending_table_mutations_through(freeze)
            .await
            .map_err(|_| Error::RuntimeUnavailable)?;
        if mutations.is_empty() || freeze.checkpoint.mutation_sequence == 0 {
            return Err(Error::IncompleteStaging);
        }
        let current_store_root = format
            .load_row_map(
                mutations[0]
                    .table_object_id()
                    .ok_or(Error::IncompleteStaging)?
                    .bytes(),
            )
            .map_err(|_| Error::RepositoryUnavailable)?
            .version()
            .store_root()
            .clone();
        let (graph, store_root, logical_rekeys) =
            build_frozen_publication_store_root(repository, expected_head, &mutations)?;
        if store_root == current_store_root && logical_rekeys.is_empty() {
            return Ok(None);
        }
        let candidate = build_private_publication_candidate_with_store_root(
            repository,
            expected_head,
            &graph,
            &store_root,
            message,
        )?;
        // Store-only candidates still need a durable journal anchor. Keep the
        // format metadata file unchanged rather than projecting row keys into
        // legacy loose paths.
        let marker =
            ManagedPath::new(".orna/database.orna").map_err(|_| Error::RepositoryUnavailable)?;
        let paths = [marker.clone()];
        let captured = repository
            .capture_managed_publication_state(expected_head, &expected_index, &paths)
            .map_err(map_publication_repository_error)?;
        let expected = captured
            .into_iter()
            .next()
            .ok_or(Error::RepositoryUnavailable)?;
        let entry = PublicationJournalEntry::new(marker, expected.clone(), expected);
        let base_index_tree = expected_index
            .tree()
            .cloned()
            .ok_or(Error::IncompleteStaging)?;
        let journal = PublicationJournal::new_with_runtime_intent(
            expected_head.clone(),
            candidate.commit().clone(),
            base_index_tree,
            freeze.intent_id,
            vec![entry],
        )
        .and_then(|journal| journal.with_store_root(&store_root))
        .and_then(|journal| journal.with_logical_rekeys(logical_rekeys))
        .map_err(|_| Error::RepositoryUnavailable)?;
        let protected_source_mutations = mutations
            .iter()
            .filter(|mutation| !mutation.protected_content_transfers().is_empty())
            .cloned()
            .collect();
        Ok(Some(Self {
            expected_index,
            candidate,
            journal,
            protected_source_mutations,
        }))
    }

    pub fn candidate(&self) -> &PrivateCommit {
        &self.candidate
    }

    pub fn journal(&self) -> &PublicationJournal {
        &self.journal
    }

    /// Executes repository ref, index, and worktree boundaries. The journal
    /// intentionally remains at `WorktreeReconciled` after this returns.
    pub fn publish(&mut self, repository: &Repository) -> Result<IndexGeneration, Error> {
        self.publish_with_stage_hook(repository, |_| {})
    }

    /// Observes durable ref and index journal stages.
    pub fn publish_with_stage_hook(
        &mut self,
        repository: &Repository,
        on_stage: impl FnMut(orna_repository_v1::PublicationJournalStage),
    ) -> Result<IndexGeneration, Error> {
        repository
            .publish_candidate_with_stage_hook(
                &self.expected_index,
                &self.candidate,
                &mut self.journal,
                on_stage,
            )
            .map_err(map_publication_repository_error)
    }

    /// Completes the runtime transaction first, then advances and clears the
    /// repository journal. Runtime completion is idempotent, so a failure
    /// between these two durable steps remains recoverable.
    pub async fn complete(
        &mut self,
        repository: &Repository,
        runtime: &RuntimeState,
        freeze: &PublicationFreeze,
    ) -> Result<(), Error> {
        if freeze.intent_id
            != self
                .journal
                .runtime_intent_id()
                .ok_or(Error::InvalidTransition)?
        {
            return Err(Error::InvalidTransition);
        }
        let commit = PublicationCommitId::new(self.candidate.commit().as_str().as_bytes().to_vec())
            .map_err(|_| Error::InvalidObjectId)?;
        if self.journal.stage() != orna_repository_v1::PublicationJournalStage::WorktreeReconciled {
            return Err(Error::PublicationPending);
        }
        if repository
            .head()
            .map_err(map_publication_repository_error)?
            .as_ref()
            != Some(self.journal.new_head())
        {
            return Err(Error::RefConflict);
        }
        runtime
            .complete_publication(freeze, &commit)
            .await
            .map_err(|_| Error::RuntimeUnavailable)?;
        repository
            .mark_runtime_complete(freeze.intent_id, &mut self.journal)
            .map_err(|_| Error::RepositoryUnavailable)?;
        self.protected_source_mutations.clear();
        Ok(())
    }

    /// Recovers a persisted runtime publication after a process interruption.
    /// Repository reconciliation is completed before the runtime prefix is
    /// consumed; every mismatch leaves the journal and pending tail intact.
    ///
    /// A journal left by a retired loose or compact writer fails with
    /// [`Error::LegacyReadOnly`] before any ref, index, worktree or runtime
    /// change: this build cannot finish a legacy publication.
    pub async fn recover(
        repository: &Repository,
        runtime: &RuntimeState,
    ) -> Result<Option<IndexGeneration>, Error> {
        let Some(journal) = repository
            .read_publication_journal()
            .map_err(map_publication_repository_error)?
        else {
            // Without a journal, an Orna-marked lock may still have been left
            // before Prepared; the repository reclaims it before reporting none.
            return repository
                .recover_publication()
                .map_err(map_publication_repository_error);
        };
        refuse_retired_writer_journal(repository, &journal)?;
        if repository
            .publication_journal_is_reviewed(&journal)
            .map_err(map_publication_repository_error)?
        {
            // A reviewed commit is completed by `commit_reviewed_candidate`,
            // which records its runtime intent with `mark_runtime_complete`.
            // It never had a runtime freeze, so none is requested here.
            return match repository.recover_publication() {
                Ok(index) => Ok(index),
                Err(RepositoryError::PublicationPending | RepositoryError::RuntimeCompletionRequired) => {
                    Err(Error::PublicationPending)
                }
                Err(error) => Err(map_publication_repository_error(error)),
            };
        }
        let intent_id = journal
            .runtime_intent_id()
            .ok_or(Error::InvalidTransition)?;
        let freeze = runtime
            .publication_freeze(intent_id)
            .await
            .map_err(|_| Error::RuntimeUnavailable)?;
        let commit = PublicationCommitId::new(journal.new_head().as_str().as_bytes().to_vec())
            .map_err(|_| Error::InvalidObjectId)?;

        if matches!(
            journal.stage(),
            orna_repository_v1::PublicationJournalStage::RuntimeCompleted
                | orna_repository_v1::PublicationJournalStage::Complete
        ) {
            runtime
                .complete_publication(&freeze, &commit)
                .await
                .map_err(|_| Error::RuntimeUnavailable)?;
            return repository
                .recover_publication()
                .map_err(|_| Error::RepositoryUnavailable);
        }

        match repository.recover_publication() {
            Ok(index) => return Ok(index),
            Err(RepositoryError::PublicationPending) => {
                return Err(Error::PublicationPending);
            }
            Err(RepositoryError::RuntimeCompletionRequired) => {}
            Err(error) => return Err(map_publication_repository_error(error)),
        }

        let mut journal = repository
            .read_publication_journal()
            .map_err(map_publication_repository_error)?
            .ok_or(Error::InvalidTransition)?;
        if journal.stage() != orna_repository_v1::PublicationJournalStage::WorktreeReconciled
            || journal.runtime_intent_id() != Some(intent_id)
        {
            return Err(Error::InvalidTransition);
        }
        if repository
            .head()
            .map_err(map_publication_repository_error)?
            .as_ref()
            != Some(journal.new_head())
        {
            return Err(Error::RefConflict);
        }
        runtime
            .complete_publication(&freeze, &commit)
            .await
            .map_err(|_| Error::RuntimeUnavailable)?;
        repository
            .mark_runtime_complete(intent_id, &mut journal)
            .map_err(|_| Error::RepositoryUnavailable)?;
        repository
            .index_generation()
            .map(Some)
            .map_err(|_| Error::RepositoryUnavailable)
    }
}

fn map_publication_repository_error(error: RepositoryError) -> Error {
    match error {
        RepositoryError::InvalidPublicationJournal | RepositoryError::InvalidCompactManifest => {
            Error::InvalidPublicationJournal
        }
        RepositoryError::StaleIndex { .. } => Error::RecoveryIndexConflict,
        RepositoryError::StaleHead => Error::RefConflict,
        RepositoryError::ManagedContentConflict => Error::ManagedWorktreeConflict,
        RepositoryError::PublicationPending => Error::PublicationPending,
        RepositoryError::RuntimeCompletionRequired => Error::InvalidTransition,
        _ => Error::RepositoryUnavailable,
    }
}

/// Opens the committed format context at `snapshot` only when that snapshot
/// has a row writer. Format-1/2 commits keep their versioned readers, but the
/// loose and compact row writers are retired (ORNA-UPGRADE-003, ORNA-ROW-013).
/// They fail with [`Error::LegacyReadOnly`], so publication onto them writes
/// nothing until the repository is migrated to format 3.
pub fn writable_snapshot_context(
    repository: &Repository,
    snapshot: &GitCommitRef,
) -> Result<HistoricalFormatContext, Error> {
    let context = repository
        .open_format_context_at_selector(snapshot.as_str())
        .map_err(|_| Error::RepositoryUnavailable)?;
    match context.repository_format() {
        RepositoryFormat::Format3 => Ok(context),
        legacy => Err(Error::LegacyReadOnly {
            format: legacy.number(),
        }),
    }
}

/// Refuses a publication journal written by a retired legacy writer. Only the
/// compact writer recorded a compact witness, and a non-migration journal over
/// a format-1/2 snapshot came from the loose writer. This build can finish
/// neither, so the journal, ref, index, worktree and runtime tail stay as
/// they are. A migration journal is the format-3 transition itself.
fn refuse_retired_writer_journal(
    repository: &Repository,
    journal: &PublicationJournal,
) -> Result<(), Error> {
    let compact = journal.compact_manifest().is_some();
    if !compact && journal.migration_continuity().is_some() {
        return Ok(());
    }
    match writable_snapshot_context(repository, journal.old_head()) {
        Err(error @ Error::LegacyReadOnly { .. }) => Err(error),
        // A compact witness over anything but a legacy base is malformed.
        _ if compact => Err(Error::InvalidPublicationJournal),
        _ => Ok(()),
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum Error {
    InvalidTableRoot,
    InvalidKey,
    UnsafePath,
    IncompleteStaging,
    InvalidObjectId,
    /// The publication target is a format-1/2 compatibility snapshot. It
    /// remains readable, but it has no row writer until it is migrated to
    /// format 3.
    LegacyReadOnly {
        format: u8,
    },
    RecoveryIndexConflict,
    RefConflict,
    ManagedWorktreeConflict,
    PublicationPending,
    InvalidPublicationJournal,
    InvalidTransition,
    RuntimeUnavailable,
    RepositoryUnavailable,
}
impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::InvalidTableRoot => "invalid table root",
            Self::InvalidKey => "invalid loose row key",
            Self::UnsafePath => "unsafe loose row path",
            Self::IncompleteStaging => "incomplete publication staging",
            Self::InvalidObjectId => "invalid object id",
            Self::LegacyReadOnly { format } => {
                return write!(
                    f,
                    "repository format {format} is a read-only legacy snapshot; migrate it to format 3 before publishing"
                );
            }
            Self::RecoveryIndexConflict => "recovery index conflict",
            Self::RefConflict => "publication ref conflict",
            Self::ManagedWorktreeConflict => "managed worktree content conflict",
            Self::PublicationPending => "publication remains pending before ref advance",
            Self::InvalidPublicationJournal => "invalid publication journal",
            Self::InvalidTransition => "invalid publication transition",
            Self::RuntimeUnavailable => "runtime contract unavailable",
            Self::RepositoryUnavailable => "repository projection is unavailable",
        })
    }
}
impl std::error::Error for Error {}

#[cfg(test)]
mod tests {
    use super::*;
    use base64::{Engine, engine::general_purpose::STANDARD as BASE64};
    use bytes::Bytes;
    use orna_foundation_v1::{CanonicalValue, OvbRaw};
    use orna_repository_v1::{
        CompactManifest, CompactPublicationPlan, CompactSegment, CompactSegmentRole,
        ManagedFileChange, Uuid,
    };
    use parquet::file::{
        metadata::{FileMetaData, KeyValue, ParquetMetaData, ParquetMetaDataWriter},
        reader::{FileReader, SerializedFileReader},
    };
    use sha2::{Digest, Sha256};
    use std::{fs, path::Path, process::Command};
    use tempfile::TempDir;

    fn git(directory: &Path, arguments: &[&str]) {
        assert!(
            Command::new("git")
                .current_dir(directory)
                .args(arguments)
                .status()
                .unwrap()
                .success()
        );
    }

    fn git_output(directory: &Path, arguments: &[&str]) -> String {
        let output = Command::new("git")
            .current_dir(directory)
            .args(arguments)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "git {arguments:?}: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        String::from_utf8(output.stdout)
            .unwrap()
            .trim_end_matches(['\r', '\n'])
            .to_owned()
    }

    fn repository() -> (TempDir, Repository) {
        let temp = TempDir::new().unwrap();
        git(temp.path(), &["init", "-b", "main"]);
        git(
            temp.path(),
            &["config", "user.email", "kieran@drewett.dev"],
        );
        git(temp.path(), &["config", "user.name", "kierandrewett"]);
        git(temp.path(), &["config", "commit.gpgsign", "false"]);
        fs::write(temp.path().join("main.orna"), "module main;\n").unwrap();
        fs::write(temp.path().join("ordinary.txt"), "base\n").unwrap();
        git(temp.path(), &["add", "."]);
        git(temp.path(), &["commit", "-m", "initial"]);
        let repository = Repository::discover(temp.path()).unwrap();
        (temp, repository)
    }

    fn decode_base64(value: &str) -> Vec<u8> {
        fn digit(byte: u8) -> u8 {
            match byte {
                b'A'..=b'Z' => byte - b'A',
                b'a'..=b'z' => byte - b'a' + 26,
                b'0'..=b'9' => byte - b'0' + 52,
                b'+' => 62,
                b'/' => 63,
                b'=' => 0,
                _ => panic!("invalid fixture encoding"),
            }
        }

        let bytes = value.as_bytes();
        let (chunks, remainder) = bytes.as_chunks::<4>();
        assert!(remainder.is_empty());
        let mut decoded = Vec::with_capacity(bytes.len() / 4 * 3);
        for chunk in chunks {
            let word = (u32::from(digit(chunk[0])) << 18)
                | (u32::from(digit(chunk[1])) << 12)
                | (u32::from(digit(chunk[2])) << 6)
                | u32::from(digit(chunk[3]));
            decoded.push((word >> 16) as u8);
            if chunk[2] != b'=' {
                decoded.push((word >> 8) as u8);
            }
            if chunk[3] != b'=' {
                decoded.push(word as u8);
            }
        }
        decoded
    }

    fn compact_columns() -> Vec<u8> {
        let field_id = Uuid::from_u64_pair(0x018f_0000_0000_7000, 0x8000_0000_0000_0001);
        CanonicalValue::new(OvbRaw::Array(vec![OvbRaw::Array(vec![
            OvbRaw::Array(vec![OvbRaw::Tag(
                37,
                Box::new(OvbRaw::Bytes(field_id.as_bytes().to_vec())),
            )]),
            OvbRaw::Array(vec![OvbRaw::Text(format!("f_{}", field_id.simple()))]),
            OvbRaw::Array(vec![OvbRaw::Int(0.into()), OvbRaw::Text("Int".to_owned())]),
            OvbRaw::Text("int64".to_owned()),
            OvbRaw::Array(Vec::new()),
        ])]))
        .unwrap()
        .encode()
        .unwrap()
    }

    fn compact_schema() -> orna_foundation_v1::SchemaDescriptor {
        let table = Uuid::from_u128(1);
        let field_id = Uuid::from_u64_pair(0x018f_0000_0000_7000, 0x8000_0000_0000_0001);
        orna_foundation_v1::SchemaDescriptor::new(OvbRaw::Map(vec![
            (OvbRaw::Int(0.into()), OvbRaw::Int(1.into())),
            (
                OvbRaw::Int(1.into()),
                OvbRaw::Tag(37, Box::new(OvbRaw::Bytes(table.as_bytes().to_vec()))),
            ),
            (
                OvbRaw::Int(2.into()),
                OvbRaw::Array(vec![OvbRaw::Tag(
                    37,
                    Box::new(OvbRaw::Bytes(field_id.as_bytes().to_vec())),
                )]),
            ),
            (
                OvbRaw::Int(3.into()),
                OvbRaw::Array(vec![OvbRaw::Array(vec![
                    OvbRaw::Tag(37, Box::new(OvbRaw::Bytes(field_id.as_bytes().to_vec()))),
                    OvbRaw::Text(format!("f_{}", field_id.simple())),
                    OvbRaw::Array(vec![OvbRaw::Int(0.into()), OvbRaw::Text("Int".into())]),
                    OvbRaw::Int(0.into()),
                    OvbRaw::Array(vec![OvbRaw::Int(0.into())]),
                ])]),
            ),
            (OvbRaw::Int(4.into()), OvbRaw::Array(Vec::new())),
        ]))
        .unwrap()
    }

    fn compact_schema_fingerprint(schema: &orna_foundation_v1::SchemaDescriptor) -> [u8; 32] {
        let bytes = schema.encode().unwrap();
        let mut digest = Sha256::new();
        digest.update(b"orna.schema.v1\0");
        digest.update(bytes);
        digest.finalize().into()
    }

    fn compact_schema_hex(schema: [u8; 32]) -> String {
        schema
            .into_iter()
            .map(|byte| format!("{byte:02x}"))
            .collect()
    }

    fn compact_runtime_parquet() -> (Vec<u8>, [u8; 32]) {
        const PARQUET: &str = "";
        let original = decode_base64(PARQUET);
        let reader = SerializedFileReader::new(Bytes::from(original.clone())).unwrap();
        let file = reader.metadata().file_metadata();
        let schema = compact_schema();
        let schema_ovb = schema.encode().unwrap();
        let fingerprint = compact_schema_fingerprint(&schema);
        let metadata = FileMetaData::new(
            1,
            file.num_rows(),
            file.created_by().map(str::to_owned),
            Some(vec![
                KeyValue::new("orna.profile".into(), Some("compact-storage-v1".into())),
                KeyValue::new("orna.table".into(), Some(Uuid::from_u128(1).to_string())),
                KeyValue::new(
                    "orna.schema.sha256".into(),
                    Some(compact_schema_hex(fingerprint)),
                ),
                KeyValue::new("orna.schema.ovb".into(), Some(BASE64.encode(schema_ovb))),
                KeyValue::new(
                    "orna.columns.ovb".into(),
                    Some(BASE64.encode(compact_columns())),
                ),
                KeyValue::new("orna.encoder".into(), Some("test-encoder-v1".into())),
            ]),
            file.schema_descr_ptr(),
            file.column_orders().cloned(),
        );
        let metadata = ParquetMetaData::new(metadata, reader.metadata().row_groups().to_vec());
        let mut footer = Vec::new();
        ParquetMetaDataWriter::new(&mut footer, &metadata)
            .finish()
            .unwrap();
        let footer_start = original.len()
            - 8
            - u32::from_le_bytes(
                original[original.len() - 8..original.len() - 4]
                    .try_into()
                    .unwrap(),
            ) as usize;
        let mut bytes = original[..footer_start].to_vec();
        bytes.extend(footer);
        (bytes, fingerprint)
    }

    /// Builds a compact candidate and its journal with the test-only legacy
    /// fixture writer, exactly as the retired compact writer left them before
    /// its ref advanced.
    fn legacy_compact_plan(
        repository: &Repository,
        freeze: &PublicationFreeze,
    ) -> CompactPublicationPlan {
        let (parquet, schema) = compact_runtime_parquet();
        let table = Uuid::from_u128(1);
        let segment_id = Uuid::from_u64_pair(0x018f_0000_0000_7000, 0x8000_0000_0000_0001);
        let segment_path = ManagedPath::new(format!(
            ".orna/storage/{table}/data/{}/{segment_id}.parquet",
            &segment_id.to_string()[..2]
        ))
        .unwrap();
        let segment = CompactSegment::new(
            segment_id,
            CompactSegmentRole::Data,
            schema,
            "test-encoder-v1",
            segment_path,
            parquet,
            CanonicalValue::int(1.into()).encode().unwrap(),
            CanonicalValue::int(1.into()).encode().unwrap(),
            1,
            compact_columns(),
            true,
            false,
        )
        .unwrap();
        let head = repository.head().unwrap().unwrap();
        repository
            .prepare_compact_publication(
                &head,
                repository.index_generation().unwrap(),
                CompactManifest::empty(table, schema),
                freeze.intent_id,
                freeze.checkpoint.digest,
                &[segment],
                "orna: publish compact runtime data",
            )
            .unwrap()
    }

    /// A committed format-1/2 snapshot: the legacy `format.orna` coordinate
    /// beside the legacy `database.orna` sidecar.
    fn legacy_repository(format: u8) -> (TempDir, Repository) {
        let (temp, _) = repository();
        fs::create_dir_all(temp.path().join(".orna")).unwrap();
        fs::write(
            temp.path().join(".orna/format.orna"),
            format!("format {format}\n"),
        )
        .unwrap();
        fs::write(
            temp.path().join(".orna/database.orna"),
            "{database_id: \"9f237b7e-6844-4498-bcd5-d24641c07449\"}\n",
        )
        .unwrap();
        git(temp.path(), &["add", ".orna"]);
        git(temp.path(), &["commit", "-m", "legacy format metadata"]);
        let repository = Repository::discover(temp.path()).unwrap();
        (temp, repository)
    }

    /// A committed format-3 snapshot: the canonical `database.orna` record.
    fn format3_repository() -> (TempDir, Repository) {
        let (temp, _) = repository();
        fs::create_dir_all(temp.path().join(".orna")).unwrap();
        fs::write(
            temp.path().join(".orna/database.orna"),
            "{\n    repository_format: 3,\n    database_id: \"9f237b7e-6844-4498-bcd5-d24641c07449\",\n}\n",
        )
        .unwrap();
        git(temp.path(), &["add", ".orna"]);
        git(temp.path(), &["commit", "-m", "format-3 metadata"]);
        let repository = Repository::discover(temp.path()).unwrap();
        (temp, repository)
    }

    /// Opens a runtime holding one committed row and freezes it, so a
    /// publication has a real prefix to refuse.
    async fn frozen_runtime(repository: &Repository) -> (RuntimeState, PublicationFreeze) {
        let runtime = RuntimeState::open(
            repository,
            orna_runtime_v1::RuntimeIdentity {
                database_id: [91; 16],
                repository_id: [92; 16],
            },
            [93; 32],
        )
        .await
        .unwrap();
        let lease = runtime.acquire_lease([94; 16]).await.unwrap();
        let context = runtime.begin_activation().await.unwrap();
        runtime
            .commit_table_activation(
                lease,
                &context,
                &[
                    TableMutation::new([95; 16], "Contact", b"Alice".to_vec(), Some(b"row".to_vec()))
                        .unwrap(),
                ],
                [96; 32],
                &orna_runtime_v1::NoFault,
            )
            .await
            .unwrap();
        let freeze = runtime
            .freeze(
                [97; 16],
                &orna_runtime_v1::Checkpoint {
                    generation: 1,
                    digest: [96; 32],
                    mutation_sequence: 1,
                },
            )
            .await
            .unwrap();
        (runtime, freeze)
    }

    /// Everything a refused publication must leave untouched: the ref, the
    /// index, the worktree, the object store and the publication journal.
    fn publication_state(
        root: &Path,
        repository: &Repository,
    ) -> (
        Option<GitCommitRef>,
        IndexGeneration,
        String,
        String,
        Option<PublicationJournal>,
    ) {
        (
            repository.head().unwrap(),
            repository.index_generation().unwrap(),
            git_output(root, &["status", "--porcelain", "--untracked-files=all"]),
            git_output(root, &["count-objects", "-v"]),
            repository.read_publication_journal().unwrap(),
        )
    }

    #[test]
    fn coordinator_preserves_changed_ref_conflict() {
        assert!(matches!(
            map_publication_repository_error(RepositoryError::StaleHead),
            Error::RefConflict
        ));
    }

    #[tokio::test]
    async fn coordinator_recovery_preserves_a_malformed_journal_read() {
        let (_temp, repository) = repository();
        let runtime = RuntimeState::open(
            &repository,
            orna_runtime_v1::RuntimeIdentity {
                database_id: [61; 16],
                repository_id: [62; 16],
            },
            [63; 32],
        )
        .await
        .unwrap();
        fs::create_dir_all(repository.runtime_paths().root()).unwrap();
        fs::write(
            repository
                .runtime_paths()
                .root()
                .join("publication-journal.bin"),
            b"truncated journal",
        )
        .unwrap();

        assert!(matches!(
            RuntimePublicationCoordinator::recover(&repository, &runtime).await,
            Err(Error::InvalidPublicationJournal)
        ));
        assert_eq!(
            fs::read(
                repository
                    .runtime_paths()
                    .root()
                    .join("publication-journal.bin")
            )
            .unwrap(),
            b"truncated journal"
        );
    }

    #[test]
    fn logical_keys_are_encoded_before_path_safety_validation() {
        for (key, encoded) in [
            ("", "~ff"),
            (".", "~2e"),
            ("..", "~2e~2e"),
            ("foo/bar", "foo~2fbar"),
            ("foo\\bar", "foo~5cbar"),
            ("/outside", "~2foutside"),
            (".git", "~2egit"),
            ("con", "~63on"),
            ("é", "~c3~a9"),
        ] {
            let path = LoosePath::for_key("Contact", &[key.into()]).unwrap();
            assert_eq!(
                path.as_managed_path().as_path(),
                std::path::Path::new(&format!("Contact/{encoded}.orna"))
            );
            assert_eq!(orna_value_v1::path_decode_component(encoded).unwrap(), key);
        }
        let composite = LoosePath::for_key("Contact", &["..".into(), "a/b".into()]).unwrap();
        assert_eq!(
            composite.as_managed_path().as_path(),
            std::path::Path::new("Contact/~2e~2e/a~2fb.orna")
        );
        assert!(LoosePath::for_key("Contact", &[]).is_err());
        assert!(LoosePath::for_key("Contact", &["a".repeat(201)]).is_err());
        assert!(LoosePath::for_key("Contact", &vec!["a".repeat(200); 6]).is_err());
        for root in ["", ".", "..", "../Contact", "/Contact", "a\\b"] {
            assert!(LoosePath::for_key(root, &["safe".into()]).is_err());
        }
    }
    #[test]
    fn discovered_paths_must_be_canonical_before_admission() {
        for (keys, components) in [
            (vec![""], vec!["~ff.orna"]),
            (vec!["..", "foo/bar"], vec!["~2e~2e", "foo~2fbar.orna"]),
            (
                vec!["first.orna", "last.orna"],
                vec!["first.orna", "last.orna.orna"],
            ),
        ] {
            let keys: Vec<String> = keys.into_iter().map(String::from).collect();
            let components: Vec<String> = components.into_iter().map(String::from).collect();
            let discovered = LoosePath::from_encoded_key("Contact", &components).unwrap();
            assert_eq!(discovered, LoosePath::for_key("Contact", &keys).unwrap());
            assert_eq!(
                discovered.as_managed_path().as_path(),
                std::path::Path::new(&format!("Contact/{}", components.join("/")))
            );
        }
        for components in [
            vec![],
            vec!["alice"],
            vec!["~61lice.orna"],
            vec!["~FF.orna"],
            vec!["..", "alice.orna"],
            vec!["/alice.orna"],
            vec!["a\\alice.orna"],
        ] {
            let components: Vec<String> = components.into_iter().map(String::from).collect();
            assert_eq!(
                LoosePath::from_encoded_key("Contact", &components),
                Err(Error::InvalidKey)
            );
        }
        assert!(LoosePath::from_encoded_key("../Contact", &["alice.orna".into()]).is_err());
    }

    #[tokio::test]
    async fn legacy_head_is_refused_before_any_publication_write() {
        for format in [1, 2] {
            let (temp, repository) = legacy_repository(format);
            let (runtime, freeze) = frozen_runtime(&repository).await;
            let head = repository.head().unwrap().unwrap();
            let before = publication_state(temp.path(), &repository);
            let pending = runtime.pending().await.unwrap();
            let path_for =
                |mutation: &TableMutation| LoosePath::for_key(mutation.table(), &["Alice".into()]);

            assert_eq!(
                RuntimePublicationCoordinator::prepare_allow_noop(
                    &repository,
                    &runtime,
                    &head,
                    repository.index_generation().unwrap(),
                    &freeze,
                    path_for,
                    "orna: publish runtime data",
                )
                .await,
                Err(Error::LegacyReadOnly { format })
            );
            assert_eq!(
                RuntimePublicationCoordinator::prepare(
                    &repository,
                    &runtime,
                    &head,
                    repository.index_generation().unwrap(),
                    &freeze,
                    path_for,
                    "orna: publish runtime data",
                )
                .await,
                Err(Error::LegacyReadOnly { format })
            );

            // No candidate object, ref, index, worktree row or journal was
            // written, and the frozen prefix is still pending.
            assert_eq!(publication_state(temp.path(), &repository), before);
            assert!(!temp.path().join("Contact").exists());
            assert_eq!(runtime.pending().await.unwrap(), pending);
            assert_eq!(runtime.pending_through(&freeze).await.unwrap().len(), 1);
            // The legacy commit stays readable through its versioned reader.
            assert_eq!(
                repository
                    .open_format_context_at_selector(head.as_str())
                    .unwrap()
                    .repository_format_number(),
                format
            );
        }
        assert_eq!(
            Error::LegacyReadOnly { format: 2 }.to_string(),
            "repository format 2 is a read-only legacy snapshot; migrate it to format 3 before publishing"
        );
    }

    #[tokio::test]
    async fn recovery_refuses_a_retired_loose_journal_without_touching_it() {
        let (temp, repository) = legacy_repository(2);
        let (runtime, freeze) = frozen_runtime(&repository).await;
        let head = repository.head().unwrap().unwrap();
        let index = repository.index_generation().unwrap();
        let path = LoosePath::for_key("Contact", &["Alice".into()]).unwrap();
        let candidate = repository
            .build_private_commit(
                &head,
                &[ManagedFileChange::new(
                    path.as_managed_path().clone(),
                    Some(b"row".to_vec()),
                )],
                "orna: publish runtime data",
            )
            .unwrap();
        let journal = PublicationJournal::new_with_runtime_intent(
            head.clone(),
            candidate.commit().clone(),
            index.tree().unwrap().clone(),
            freeze.intent_id,
            vec![PublicationJournalEntry::new(
                path.as_managed_path().clone(),
                None,
                Some(b"row".to_vec()),
            )],
        )
        .unwrap();
        repository.write_publication_journal(&journal).unwrap();
        // The retired loose writer was interrupted after advancing its ref.
        repository.advance_current_ref(&head, &candidate).unwrap();
        let before = publication_state(temp.path(), &repository);
        let pending = runtime.pending().await.unwrap();

        assert_eq!(
            RuntimePublicationCoordinator::recover(&repository, &runtime).await,
            Err(Error::LegacyReadOnly { format: 2 })
        );
        assert_eq!(publication_state(temp.path(), &repository), before);
        assert_eq!(repository.read_publication_journal().unwrap(), Some(journal));
        assert!(!temp.path().join(path.as_managed_path().as_path()).exists());
        assert_eq!(runtime.pending().await.unwrap(), pending);
    }

    #[tokio::test]
    async fn recovery_refuses_a_retired_compact_journal_without_touching_it() {
        let (temp, repository) = legacy_repository(2);
        let (runtime, freeze) = frozen_runtime(&repository).await;
        let plan = legacy_compact_plan(&repository, &freeze);
        repository.write_publication_journal(plan.journal()).unwrap();
        let before = publication_state(temp.path(), &repository);
        let pending = runtime.pending().await.unwrap();

        assert_eq!(
            RuntimePublicationCoordinator::recover(&repository, &runtime).await,
            Err(Error::LegacyReadOnly { format: 2 })
        );
        assert_eq!(publication_state(temp.path(), &repository), before);
        assert_eq!(
            repository.read_publication_journal().unwrap().as_ref(),
            Some(plan.journal())
        );
        assert_eq!(runtime.pending().await.unwrap(), pending);
    }

    /// Only the retired compact writer recorded a compact witness, and it
    /// wrote only onto format-1/2 snapshots. Over a readable format-3 base the
    /// witness is malformed evidence, so recovery refuses the journal.
    #[tokio::test]
    async fn recovery_refuses_a_compact_journal_without_a_legacy_base() {
        let (temp, repository) = format3_repository();
        let (runtime, freeze) = frozen_runtime(&repository).await;
        let plan = legacy_compact_plan(&repository, &freeze);
        assert!(writable_snapshot_context(&repository, plan.journal().old_head()).is_ok());
        repository.write_publication_journal(plan.journal()).unwrap();
        let before = publication_state(temp.path(), &repository);

        assert_eq!(
            RuntimePublicationCoordinator::recover(&repository, &runtime).await,
            Err(Error::InvalidPublicationJournal)
        );
        assert_eq!(publication_state(temp.path(), &repository), before);
        assert_eq!(runtime.pending_through(&freeze).await.unwrap().len(), 1);
    }
}
